
import json
import re
import sys
from pathlib import Path
from collections import defaultdict

ROOT = Path(__file__).resolve().parents[2]
ARTIFACTS = ROOT / "artifacts"

SEVERITY_WEIGHT = {
    "CRITICAL": 40,
    "HIGH": 25,
    "MEDIUM": 12,
    "LOW": 4
}

SEVERITY_ORDER = {
    "CRITICAL": 4,
    "HIGH": 3,
    "MEDIUM": 2,
    "LOW": 1
}


def load_findings(filename):
    """Load findings generated by an individual AI agent."""

    path = ARTIFACTS / filename

    if not path.exists():
        return None

    with open(path, "r", encoding="utf-8") as file:
        data = json.load(file)

    if isinstance(data, dict):
        findings = data.get("findings", [])
        return findings if isinstance(findings, list) else []

    if isinstance(data, list):
        return data

    return []


def normalize_issue(title, issue_type):
    """
    Identify different descriptions of the same issue.

    The classification uses both the issue title and issue type.
    """

    text = f"{issue_type} {title}".lower()

    # Normalize Unicode hyphens, underscores and spaces.
    text = re.sub(r"[\u2010-\u2015\u2212_-]+", " ", text)
    text = re.sub(r"\s+", " ", text).strip()

    # -------------------------------------------------
    # 1. Division by zero
    # -------------------------------------------------

    division_words = [
        "division",
        "divide",
        "dividing",
        "divisor",
        "denominator"
    ]

    has_division_word = any(
        word in text for word in division_words
    )

    has_zero_word = (
        "zero" in text
        or re.search(r"\b0\b", text) is not None
    )

    if has_division_word and has_zero_word:
        return "division by zero"

    # -------------------------------------------------
    # 2. SQL injection / unsafe SQL construction
    # -------------------------------------------------

    sql_construction_terms = [
        "injection",
        "concatenation",
        "concatenating",
        "string construction",
        "unsafe query construction",
        "unsafe query",
        "dynamic sql"
    ]

    if (
        "sql" in text
        and any(term in text for term in sql_construction_terms)
    ):
        return "sql injection"

    # -------------------------------------------------
    # 3. Missing database error handling
    # -------------------------------------------------

    database_words = [
        "database",
        "db "
    ]

    error_words = [
        "error",
        "exception"
    ]

    handling_words = [
        "handling",
        "uncaught",
        "unhandled",
        "missing",
        "not handled"
    ]

    has_database = any(
        word in text for word in database_words
    )

    has_error = any(
        word in text for word in error_words
    )

    has_handling = any(
        word in text for word in handling_words
    )

    if has_database and has_error and has_handling:
        return "missing database error handling"

    # -------------------------------------------------
    # 4. Other common issue categories
    # -------------------------------------------------

    aliases = {
        "command injection": [
            "command injection"
        ],

        "hardcoded secret": [
            "hardcoded secret",
            "hard coded secret",
            "hardcoded password",
            "hardcoded api key"
        ],

        "path traversal": [
            "path traversal",
            "directory traversal"
        ],

        "unsafe deserialization": [
            "unsafe deserialization",
            "insecure deserialization"
        ],

        "cross site scripting": [
            "cross site scripting",
            "xss"
        ],

        "unnecessary temporary variable": [
            "unnecessary temporary variable",
            "unnecessary variable",
            "redundant variable",
            "unused temporary variable"
        ]
    }

    for canonical_name, phrases in aliases.items():
        if any(phrase in text for phrase in phrases):
            return canonical_name

    # Fallback for issues not covered above.
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


def combine_findings(agent_results):
    """
    Combine findings from all agents.

    Same file + same line + same normalized issue
    is treated as one finding.
    """

    grouped = {}

    for agent_name, findings in agent_results.items():

        for finding in findings:

            if not isinstance(finding, dict):
                continue

            filename = finding.get("filename", "unknown")
            line_number = finding.get("line_number")

            try:
                line_number = int(line_number)
            except (TypeError, ValueError):
                continue

            if line_number < 1:
                continue

            title = str(
                finding.get("title", "Code issue")
            )

            issue_type = str(
                finding.get("issue_type", "General")
            )

            issue_key = normalize_issue(title, issue_type)

            # Unique finding identity.
            key = (
                filename,
                line_number,
                issue_key
            )

            severity = str(
                finding.get("severity", "LOW")
            ).upper()

            if severity not in SEVERITY_ORDER:
                severity = "LOW"

            try:
                confidence = float(
                    finding.get("confidence", 0.5)
                )
            except (TypeError, ValueError):
                confidence = 0.5

            confidence = max(
                0.0,
                min(1.0, confidence)
            )

            explanation = str(
                finding.get("explanation", "")
            )

            suggested_fix = str(
                finding.get("suggested_fix", "")
            )

            current = {
                "filename": filename,
                "line_number": line_number,
                "issue_type": issue_type,
                "issue_key": issue_key,
                "severity": severity,
                "title": title,
                "explanation": explanation,
                "suggested_fix": suggested_fix,
                "confidence": confidence,
                "agents": [agent_name]
            }

            if key not in grouped:
                grouped[key] = current

            else:
                existing = grouped[key]

                # Retain the highest severity reported.
                if (
                    SEVERITY_ORDER[severity]
                    > SEVERITY_ORDER[existing["severity"]]
                ):
                    existing["severity"] = severity

                # Retain the highest confidence.
                existing["confidence"] = max(
                    existing["confidence"],
                    confidence
                )

                # Track all agents that detected the issue.
                if agent_name not in existing["agents"]:
                    existing["agents"].append(agent_name)

                # Keep the most detailed explanation.
                if len(explanation) > len(existing["explanation"]):
                    existing["explanation"] = explanation

                # Keep the most detailed suggested fix.
                if len(suggested_fix) > len(existing["suggested_fix"]):
                    existing["suggested_fix"] = suggested_fix

                # Prefer the title associated with higher severity.
                if (
                    SEVERITY_ORDER[severity]
                    > SEVERITY_ORDER.get(
                        existing.get("_previous_severity", severity),
                        0
                    )
                ):
                    existing["title"] = title

    results = list(grouped.values())

    results.sort(
        key=lambda item: (
            -SEVERITY_ORDER[item["severity"]],
            item["filename"],
            item["line_number"]
        )
    )

    return results


def calculate_risk(findings):
    """
    Calculate risk using unique findings only.

    Formula:
    Risk contribution = Severity weight * Confidence

    Maximum score = 100.
    """

    total_score = 0

    for finding in findings:
        weight = SEVERITY_WEIGHT[finding["severity"]]
        confidence = finding["confidence"]

        total_score += weight * confidence

    score = min(100, round(total_score))

    if any(
        finding["severity"] == "CRITICAL"
        for finding in findings
    ):
        level = "CRITICAL"

    elif any(
        finding["severity"] == "HIGH"
        for finding in findings
    ):
        level = "HIGH"

    elif any(
        finding["severity"] == "MEDIUM"
        for finding in findings
    ):
        level = "MEDIUM"

    elif findings:
        level = "LOW"

    else:
        level = "NO ISSUES"

    return score, level


def generate_summary(findings, score, level):
    """Generate a readable Markdown review summary."""

    counts = defaultdict(int)

    for finding in findings:
        counts[finding["severity"]] += 1

    lines = [
        "# AI Pull Request Review",
        "",
        f"**Risk score:** {score}/100",
        f"**Risk level:** {level}",
        "",
        "## Findings",
        "",
        f"- Total unique findings: {len(findings)}",
        f"- Critical: {counts['CRITICAL']}",
        f"- High: {counts['HIGH']}",
        f"- Medium: {counts['MEDIUM']}",
        f"- Low: {counts['LOW']}",
        "",
        "## Detailed Findings",
        ""
    ]

    if not findings:
        lines.append("No actionable issues were reported.")

    for finding in findings:
        lines.extend([
            f"### [{finding['severity']}] {finding['title']}",
            "",
            f"- **File:** `{finding['filename']}`",
            f"- **Line:** {finding['line_number']}",
            f"- **Issue category:** {finding['issue_key']}",
            f"- **Detected by:** {', '.join(finding['agents'])}",
            f"- **Confidence:** {finding['confidence']:.0%}",
            f"- **Explanation:** {finding['explanation']}",
            f"- **Suggested fix:** {finding['suggested_fix']}",
            ""
        ])

    return "\n".join(lines)


def main():

    pr_number = sys.argv[1] if len(sys.argv) > 1 else "1"

    if not pr_number.isdigit() or int(pr_number) < 1:
        print("ERROR: Invalid pull request number.")
        return

    input_files = {
        "Bug Finder": f"pr_{pr_number}_bug_findings.json",
        "Security Checker": f"pr_{pr_number}_security_findings.json",
        "Style Reviewer": f"pr_{pr_number}_style_findings.json"
    }

    print(
        f"\nCombining AI review results for PR #{pr_number}...\n"
    )

    agent_results = {}

    for agent_name, filename in input_files.items():

        findings = load_findings(filename)

        if findings is None:
            print(f"MISSING: {filename}")
            print(f"Run the {agent_name} first.")
            return

        agent_results[agent_name] = findings

        print(
            f"{agent_name}: {len(findings)} finding(s)"
        )

    # Combine and deduplicate all agent findings.
    combined = combine_findings(agent_results)

    # Calculate final risk.
    score, level = calculate_risk(combined)

    # Generate readable summary.
    summary = generate_summary(
        combined,
        score,
        level
    )

    # Final JSON report.
    report = {
        "pull_request": int(pr_number),
        "total_findings": len(combined),
        "risk_score": score,
        "risk_level": level,
        "findings": combined
    }

    ARTIFACTS.mkdir(
        parents=True,
        exist_ok=True
    )

    report_path = (
        ARTIFACTS / f"pr_{pr_number}_review_report.json"
    )

    summary_path = (
        ARTIFACTS / f"pr_{pr_number}_review_summary.md"
    )

    with open(
        report_path,
        "w",
        encoding="utf-8"
    ) as file:
        json.dump(
            report,
            file,
            indent=4
        )

    with open(
        summary_path,
        "w",
        encoding="utf-8"
    ) as file:
        file.write(summary)

    print("\nSUCCESS! Review coordination completed.")

    print(f"Total unique findings: {len(combined)}")
    print(f"Risk score: {score}/100")
    print(f"Risk level: {level}")

    print("\nFinal unique findings:")

    for finding in combined:
        print(
            f"[{finding['severity']}] "
            f"{finding['filename']}:"
            f"{finding['line_number']} "
            f"{finding['issue_key']} "
            f"(Agents: {', '.join(finding['agents'])})"
        )

    print(f"\nReport saved: {report_path}")
    print(f"Summary saved: {summary_path}")


if __name__ == "__main__":
    main()




